/**
 * 抽屉便条：本机先写，登录后跟着账号走。
 *
 * 每个抽屉最多 DRAWER_NOTE_LIMIT 条（shared 里的常量，前端禁用按钮和后端拒写
 * 用的是同一个数字）。没登录、或者后端连不上时，这一层只碰 localStorage，
 * 界面照常可用；登录之后再把本机已有的便条补传到账号上（按 id 幂等），
 * 然后以服务端返回的列表为准。
 */
import {
  DRAWER_NOTE_LIMIT,
  type DrawerNote,
  type ShelfDrawerId,
} from "@leafia/shared";
import { createId } from "./createId";

export const DRAWER_NOTES_STORAGE_KEY = "leafia:home-drawer-notes:v1";
export { DRAWER_NOTE_LIMIT };

export interface NewDrawerNote {
  drawerId: ShelfDrawerId;
  title: string;
  meta?: string;
}

export function createDrawerNote(input: NewDrawerNote): DrawerNote {
  return {
    id: createId(),
    drawerId: input.drawerId,
    title: input.title.trim().slice(0, 240),
    meta: (input.meta ?? "本机便条").trim().slice(0, 240),
    createdAt: new Date().toISOString(),
  };
}

export function normalizeDrawerNotes(value: unknown): DrawerNote[] {
  if (!Array.isArray(value)) return [];
  const notes: DrawerNote[] = [];
  for (const candidate of value as Partial<DrawerNote>[]) {
    if (
      !candidate ||
      typeof candidate.id !== "string" ||
      typeof candidate.title !== "string" ||
      typeof candidate.drawerId !== "string" ||
      !["notes", "materials", "collection"].includes(candidate.drawerId)
    ) {
      continue;
    }
    notes.push({
      id: candidate.id,
      drawerId: candidate.drawerId as ShelfDrawerId,
      title: candidate.title,
      meta:
        typeof candidate.meta === "string" && candidate.meta
          ? candidate.meta
          : "本机便条",
      createdAt:
        typeof candidate.createdAt === "string"
          ? candidate.createdAt
          : new Date(0).toISOString(),
    });
  }
  return notes;
}

export function loadDrawerNotes(): DrawerNote[] {
  if (typeof localStorage === "undefined") return [];
  try {
    return normalizeDrawerNotes(
      JSON.parse(localStorage.getItem(DRAWER_NOTES_STORAGE_KEY) ?? "null"),
    );
  } catch {
    return [];
  }
}

export function saveDrawerNotes(notes: DrawerNote[]) {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(DRAWER_NOTES_STORAGE_KEY, JSON.stringify(notes));
  } catch {
    // 隐私模式下写不进去也不该让抽屉打不开。
  }
}

/**
 * 这机子上那份便条属于谁。
 *
 * 记的是 userId；没登录时是 null。换账号登录时靠它区分两种情况：
 * 本机便条是自己的（或还没登录的），就补传到账号；是上一个账号留下的，
 * 就不动它 —— 否则在共用电脑上登录会被顺手拉进另一个人的账号。
 */
const DRAWER_NOTES_OWNER_KEY = "leafia:home-drawer-notes-owner:v1";

export function loadDrawerNotesOwner(): string | null {
  if (typeof localStorage === "undefined") return null;
  try {
    return localStorage.getItem(DRAWER_NOTES_OWNER_KEY);
  } catch {
    return null;
  }
}

export function saveDrawerNotesOwner(userId: string | null) {
  if (typeof localStorage === "undefined") return;
  try {
    if (userId) {
      localStorage.setItem(DRAWER_NOTES_OWNER_KEY, userId);
    } else {
      localStorage.removeItem(DRAWER_NOTES_OWNER_KEY);
    }
  } catch {
    // 同上，隐私模式下忽略。
  }
}

/**
 * 本机便条里可以跟着这次登录走的那些。
 *
 * 本机那份属于另一个账号时返回空数组：这时候账号里的列表才是真的，
 * 本机那几张贴在别人的账号上，不该被补传过去。
 */
export function localNotesForAccount(userId: string): DrawerNote[] {
  const owner = loadDrawerNotesOwner();
  return owner && owner !== userId ? [] : loadDrawerNotes();
}

export function drawerNotesIn(
  notes: DrawerNote[],
  drawerId: ShelfDrawerId,
): DrawerNote[] {
  return notes
    .filter((note) => note.drawerId === drawerId)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
}

export function drawerNoteCount(
  notes: DrawerNote[],
  drawerId: ShelfDrawerId,
): number {
  return notes.filter((note) => note.drawerId === drawerId).length;
}

export function canAddDrawerNote(
  notes: DrawerNote[],
  drawerId: ShelfDrawerId,
): boolean {
  return drawerNoteCount(notes, drawerId) < DRAWER_NOTE_LIMIT;
}

/**
 * 往本机便条里补一条，成功返回新便条，抽屉满了返回 null。
 * 阅读页把批注沉进抽屉走的就是这条路：先落本机，登录后由书架的同步逻辑补传。
 */
export function appendLocalDrawerNote(input: NewDrawerNote): DrawerNote | null {
  const notes = loadDrawerNotes();
  if (!canAddDrawerNote(notes, input.drawerId)) return null;
  const note = createDrawerNote(input);
  saveDrawerNotes([...notes, note]);
  return note;
}

/**
 * 合并账号便条与本机便条。
 *
 * 规则：先放账号里的（换设备时以账号为准），再用本机独有的便条补满空位，
 * 每个抽屉仍然封顶 DRAWER_NOTE_LIMIT。返回的列表就是要上传的清单 ——
 * 不在 remoteIds 里的那些是本机新写的，登录后按 id 补传上去。
 */
export function mergeDrawerNotes(
  remote: DrawerNote[],
  local: DrawerNote[],
): { notes: DrawerNote[]; pendingUpload: DrawerNote[] } {
  const remoteIds = new Set(remote.map((note) => note.id));
  const notes: DrawerNote[] = [];
  const pendingUpload: DrawerNote[] = [];
  for (const drawerId of ["notes", "materials", "collection"] as const) {
    const filled = drawerNotesIn(remote, drawerId);
    const localOnly = drawerNotesIn(local, drawerId).filter(
      (note) => !remoteIds.has(note.id),
    );
    for (const note of localOnly) {
      if (filled.length >= DRAWER_NOTE_LIMIT) break;
      filled.push(note);
      pendingUpload.push(note);
    }
    notes.push(...filled.slice(0, DRAWER_NOTE_LIMIT));
  }
  return { notes, pendingUpload };
}
